   130→fn dur_label(s: f64) -> String {
   131→    if s >= 60.0 {
   132→        format!("{:.1}m", s / 60.0)
   133→    } else {
   134→        format!("{:.0}s", s)
   135→    }
   136→}
   137→
   138→fn dur_label_precise(s: f64) -> String {
   139→    let total = s.max(0.0).round() as u64;
   140→    let h = total / 3600;
   141→    let m = (total % 3600) / 60;
   142→    let sec = total % 60;
   143→    if h > 0 {
   144→        format!("{h}h {m}m {sec}s")
   145→    } else if m > 0 {
   146→        format!("{m}m {sec}s")
   147→    } else {
   148→        format!("{sec}s")
   149→    }
   150→}
   151→
   152→fn format_u64_commas(n: u64) -> String {
   153→    let s = n.to_string();
   154→    let mut out = String::with_capacity(s.len() + (s.len() / 3));
   155→    for (i, ch) in s.chars().rev().enumerate() {
   156→        if i > 0 && i % 3 == 0 {
   157→            out.push(',');
   158→        }
   159→        out.push(ch);
   160→    }
   161→    out.chars().rev().collect()
   162→}
   163→
   164→fn escape_html_attr(s: &str) -> String {
   165→    let mut out = String::with_capacity(s.len());
   166→    for ch in s.chars() {
   167→        match ch {
   168→            '&' => out.push_str("&amp;"),
   169→            '<' => out.push_str("&lt;"),
   170→            '>' => out.push_str("&gt;"),
   171→            '"' => out.push_str("&quot;"),
   172→            '\'' => out.push_str("&#39;"),
   173→            _ => out.push(ch),
   174→        }
   175→    }
   176→    out
   177→}
   178→
   179→fn percentile_threshold(durations: &[f64], p: f64) -> f64 {
   180→    if durations.is_empty() {
   181→        return 0.0;
   182→    }
   183→    let mut sorted = durations.to_vec();
   184→    sorted.sort_by(|a, b| a.total_cmp(b));
   185→    let idx = ((sorted.len().saturating_sub(1)) as f64 * p).round() as usize;
   186→    sorted[idx.min(sorted.len() - 1)]
   187→}
