   189→fn peak_parallelism(bars: &[Bar]) -> usize {
   190→    let mut events: Vec<(DateTime<Utc>, i32)> = Vec::with_capacity(bars.len() * 2);
   191→    for b in bars {
   192→        events.push((b.start, 1));
   193→        events.push((b.end, -1));
   194→    }
   195→    events.sort_by(|(ta, da), (tb, db)| ta.cmp(tb).then_with(|| da.cmp(db)));
   196→
   197→    let mut cur = 0_i32;
   198→    let mut peak = 0_i32;
   199→    for (_, delta) in events {
   200→        cur += delta;
   201→        if cur > peak {
   202→            peak = cur;
   203→        }
   204→    }
   205→    peak.max(0) as usize
   206→}
