   168→            '&' => out.push_str("&amp;"),
   169→            '<' => out.push_str("&lt;"),
   170→            '>' => out.push_str("&gt;"),
   171→            '"' => out.push_str("&quot;"),
   172→            '\'' => out.push_str("&#39;"),
   173→            _ => out.push(ch),
   174→        }
   175→    }
   176→    out
   177→}
